import {
    RESET_REDUX,
    CREATE_MANUFACTURER_PRICE_DISCOUNT,
    CREATE_MANUFACTURER_PRICE_DISCOUNT_FAILED,
    CREATE_MANUFACTURER_PRICE_DISCOUNT_SUCCESS,
    UPDATE_MANUFACTURER_PRICE_DISCOUNT,
    UPDATE_MANUFACTURER_PRICE_DISCOUNT_FAILED,
    UPDATE_MANUFACTURER_PRICE_DISCOUNT_SUCCESS,
    GET_MANUFACTURER_PRICE_DISCOUNTS,
    GET_MANUFACTURER_PRICE_DISCOUNTS_SUCCESS,
    GET_MANUFACTURER_PRICE_DISCOUNTS_FAILED,
    GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID,
    GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID_SUCCESS,
    GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID_FAILED,
} from './constants';

const INIT_STATE = {
    loading: false,
    errors: [],
    success: false,
    updated: false,
    manufacturerPriceDiscounts: [],
    manufacturerPriceDiscount: null,
    count: 0,
    next: null,
    previous: null,
    message: null,
};

const DistributorPriceDiscounts = (state = INIT_STATE, action) => {
    switch (action.type) {
        case RESET_REDUX:
            return { ...state, updated: false, loading: false, success: false, message: null };

        case CREATE_MANUFACTURER_PRICE_DISCOUNT:
        case UPDATE_MANUFACTURER_PRICE_DISCOUNT:
        case GET_MANUFACTURER_PRICE_DISCOUNTS:
        case GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID:
            return {
                ...state,
                manufacturerPriceDiscounts: null,
                manufacturerPriceDiscount: null,
                success: false,
                error: null,
                loading: true,
            };

        case CREATE_MANUFACTURER_PRICE_DISCOUNT_SUCCESS:
        case UPDATE_MANUFACTURER_PRICE_DISCOUNT_SUCCESS:
            return { ...state, manufacturerPriceDiscount: action.payload, loading: false, updated: true };

        case GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID_SUCCESS:
            return { ...state, manufacturerPriceDiscount: action.payload, loading: false, updated: false };

        case GET_MANUFACTURER_PRICE_DISCOUNTS_SUCCESS:
            console.log('hapa', action.payload);
            return { ...state, manufacturerPriceDiscounts: action.payload.results, loading: false };

        case CREATE_MANUFACTURER_PRICE_DISCOUNT_FAILED:
        case UPDATE_MANUFACTURER_PRICE_DISCOUNT_FAILED:
        case GET_MANUFACTURER_PRICE_DISCOUNTS_FAILED:
        case GET_MANUFACTURER_PRICE_DISCOUNT_BY_ID_FAILED:
            return {
                ...state,
                error: action.payload.message,
                errors: action.payload.errors,
                success: false,
                loading: false,
                updated: false,
            };

        default:
            return { ...state };
    }
};

export default DistributorPriceDiscounts;
